package com.sdya.fund.service;import com.sdya.fund.repository.UserRepository;import lombok.RequiredArgsConstructor;import org.springframework.security.core.userdetails.*;import org.springframework.stereotype.Service;@Service @RequiredArgsConstructor public class UserDetailsServiceImpl implements UserDetailsService{private final UserRepository repo;public UserDetails loadUserByUsername(String u){var user=repo.findByUsername(u).orElseThrow(()->new UsernameNotFoundException("Invalid user"));return org.springframework.security.core.userdetails.User.withUsername(user.getUsername()).password(user.getPassword()).disabled(!user.isEnabled()).roles(user.getRole().name()).build();}}
